import numpy as np

def angular_sep_rad(dra_deg: float, ddec_deg: float, dec_deg: float) -> float:
    dra = np.deg2rad(dra_deg) * np.cos(np.deg2rad(dec_deg))
    ddec = np.deg2rad(ddec_deg)
    return float(np.hypot(dra, ddec))
